                return False
            try:
                self._save_locked()
            except Exception:
                self.entries[key] = previous
                raise
            return True

    def keys(self) -> list[str]:
        with self.lock:
            changed = self._purge_locked()
            if changed:
                self._save_locked()
            return sorted(self.entries)


